// ❌ OLD: A common mistake is measuring performance without warmup.
// The first invocations are INTERPRETED (level 0) — the JIT has not
// compiled anything yet, so timings look 10-100x slower than steady
// state and mislead decisions.
public class Warmup {
  static long sum(int n) {
    long s = 0;
    for (int i = 0; i < n; i++) s += i; // ❌ OLD: cold -> interpreted
    return s;
  }

  public static void main(String[] args) {
    // ❌ OLD: this measures interpretation, not the JIT'd steady state
    long t0 = System.nanoTime();
    long r = sum(1_000_000);
    System.out.println((System.nanoTime() - t0) + "ns cold");
  }
}

// ✅ NEW: Warm the method until it is JIT-compiled (tier 4, C2), then
// measure. Tiered compilation profiles and compiles hot methods, so
// steady-state timing reflects native code.
public class Warmup {
  static long sum(int n) {
    long s = 0;
    for (int i = 0; i < n; i++) s += i;
    return s;
  }

  public static void main(String[] args) {
    // ✅ NEW: warmup loop crosses the invocation thresholds -> C1 then C2
    for (int i = 0; i < 20_000; i++) sum(1_000);

    long t0 = System.nanoTime();
    long r = sum(1_000_000); // ✅ NEW: now measures compiled native code
    System.out.println((System.nanoTime() - t0) + "ns hot (" + r + ")");
  }
}
